PREFIX  owl:  <http://www.w3.org/2002/07/owl#>
PREFIX  dc:   <http://purl.org/dc/elements/1.1/>

SELECT DISTINCT  ?band
WHERE
  {   { ?band  <http://dbpedia.org/property/pastMembers>  <http://dbpedia.org/resource/Nick_Jonas> ;
               <http://dbpedia.org/property/pastMembers>  <http://dbpedia.org/resource/Kevin_Jonas> ;
               rdf:type              <http://dbpedia.org/ontology/Band>
      }
    UNION
      { ?band  <http://dbpedia.org/property/pastMembers>  <http://dbpedia.org/resource/Joe_Jonas> ;
               <http://dbpedia.org/property/pastMembers>  <http://dbpedia.org/resource/Nick_Jonas> ;
               rdf:type              <http://dbpedia.org/ontology/Band>
      }
    UNION
      { FILTER EXISTS { <http://dbpedia.org/resource/Jonas_Brothers>
                                  <http://dbpedia.org/ontology/formerBandMember>  <http://dbpedia.org/resource/Kevin_Jonas>
                      }
        BIND(<http://dbpedia.org/resource/Jonas_Brothers> AS ?band)
      }
  }

