PREFIX  owl:  <http://www.w3.org/2002/07/owl#>
PREFIX  dc:   <http://purl.org/dc/elements/1.1/>

SELECT  ?uri
WHERE
  {   { ?uri  <http://dbpedia.org/ontology/division>  <http://dbpedia.org/resource/Firmicutes> ;
              <http://dbpedia.org/property/domain>  <http://dbpedia.org/resource/Bacteria> ;
              rdf:type              <http://dbpedia.org/ontology/Bacteria>
      }
    UNION
      { PREFIX  xsd:  <http://www.w3.org/2001/XMLSchema#>
        PREFIX  rdfs: <http://www.w3.org/2000/01/rdf-schema#>
        PREFIX  rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
        PREFIX  owl:  <http://www.w3.org/2002/07/owl#>
        PREFIX  dc:   <http://purl.org/dc/elements/1.1/>

        SELECT  (COUNT(DISTINCT ?bacteria) AS ?count)
        WHERE
          { ?bacteria  <http://dbpedia.org/ontology/division>  <http://dbpedia.org/resource/Firmicutes> ;
                      <http://dbpedia.org/property/domain>  <http://dbpedia.org/resource/Bacteria> ;
                      rdf:type              <http://dbpedia.org/ontology/Bacteria>
          }
      }
    UNION
      { ?uri  <http://dbpedia.org/ontology/order>  <http://dbpedia.org/resource/Bacillales> ;
              <http://dbpedia.org/ontology/division>  <http://dbpedia.org/resource/Firmicutes> ;
              rdf:type              <http://dbpedia.org/ontology/Bacteria>
      }
  }

