SELECT DISTINCT ?mouthCountry ?countCountries ?firstAiredCountry WHERE {
  # Mouth country of Upper Neretva
  <http://dbpedia.org/resource/Upper_Neretva> <http://dbpedia.org/ontology/mouthCountry> ?mouthCountry .

  # The sea into which Upper Neretva flows
  <http://dbpedia.org/resource/Upper_Neretva> <http://dbpedia.org/ontology/riverMouth> ?sea .
  ?sea a <http://dbpedia.org/ontology/Sea> .

  # Count countries surrounding the sea
  {
    SELECT (COUNT(DISTINCT ?country) AS ?countCountries) WHERE {
      ?sea <http://dbpedia.org/ontology/country> ?country .
    }
  }

  # Country in which GM was first aired and which is also the mouth country of Upper Neretva
  <http://dbpedia.org/resource/Gümüş_(TV_series)> <http://dbpedia.org/property/firstAired> ?firstAiredCountry .
  FILTER(?firstAiredCountry = ?mouthCountry)
}
```

